if($_SERVER['REQUEST_METHOD']==='POST')try{csrf_check();$u=require_login();if(!$coupon)throw new RuntimeException('Coupon not found or expired.');db()->beginTransaction();try{$lock=db()->prepare("SELECT * FROM business_coupons WHERE id=? FOR UPDATE");$lock->execute([$coupon['id']]);$locked=$lock->fetch();if(!$locked||$locked['status']!=='active'||($locked['starts_at']&&strtotime($locked['starts_at'])>time())||($locked['ends_at']&&strtotime($locked['ends_at'])<time()))throw new RuntimeException('Coupon not found or expired.');$q=db()->prepare("SELECT COUNT(*) FROM coupon_redemptions WHERE coupon_id=? AND user_id=?");$q->execute([$coupon['id'],$u['id']]);$count=(int)$q->fetchColumn();if($count>=(int)$locked['per_user_limit'])throw new RuntimeException('You have already used this coupon the maximum number of times.');$q=db()->prepare("SELECT COUNT(*) FROM coupon_redemptions WHERE coupon_id=?");$q->execute([$coupon['id']]);$total=(int)$q->fetchColumn();if((int)$locked['max_redemptions']>0&&$total>=(int)$locked['max_redemptions'])throw new RuntimeException('Coupon redemption limit has been reached.');db()->prepare("INSERT INTO coupon_redemptions(coupon_id,user_id,amount_saved) VALUES(?,?,0)")->execute([$coupon['id'],$u['id']]);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}$msg='Coupon redeemed. Show this confirmation and code to the business.';}catch(Throwable $e){$err=$e->getMessage();}
